// Authored content for 3.2.7.2 Risk factors associated with coronary heart disease (OxfordAQA 9610 v5.1, printed p. 25;
// statements 3.2.7.2.s1–s2 in data/spec.js). Official wording: "Risk factors associated with coronary heart disease:
// diet, blood cholesterol, cigarette smoking and high blood pressure. Students should be able to analyse, interpret and
// evaluate data associated with specific risk factors and the incidence of coronary heart disease."
// Scope: the four named risk factors are required; other factors (age, sex, family history, physical inactivity,
// obesity, diabetes) are supporting. LDL/HDL, the mechanisms by which each factor acts and named drugs are supporting.
// The data skills (incidence and rates, relative and absolute risk, association v causation, confounding, study design,
// sample size, correlation, trend reliability) are required through s2. There is NO calculator for a student's own risk
// and no medical advice. Real data: B.cvdModel (PSC 2007, 4S 1994, Unal 2004) and, reused from 3.2.1, B.diseaseModel
// (Doll 2004 IHD rates; Prospective Studies Collaboration 2002 on blood pressure). Hypothetical data are labelled.
// Release review 2026-11-15: the static charts d-3.2.7.2-2 and -3 (repeated in the investigator) and the investigator's
// hazard-ratio dataset (with q-3.2.7.2-iv1 and iv2) are removed; Two towns is labelled stretch.
window.BIO = window.BIO || {}; window.BIO.content = window.BIO.content || {};
(function () {
  const A = window.BIO.cvdArt, M = window.BIO.cvdModel, DM = window.BIO.diseaseModel;
  const R = "3.2.7.2";
  const S = (...n) => n.map((k) => `${R}.s${k}`);
  const f0 = (x) => M.fix(x, 0), f1 = (x) => M.fix(x, 1), f2 = (x) => M.fix(x, 2);
  const tbl = (rows, head) => `<table class="tbl"><thead><tr>${head.map((h) => `<th>${h}</th>`).join("")}</tr></thead><tbody>${rows.map((r) => `<tr>${r.map((c) => `<td>${c}</td>`).join("")}</tr>`).join("")}</tbody></table>`;
  const n0 = (x) => Number(x).toLocaleString("en-GB");
  const link = (k, src = M.SRC) => `<a href="${src[k].url}" target="_blank" rel="noopener">${src[k].short}</a>`;
  const REAL = `<span class="badge teal">real data</span>`, HYP = `<span class="badge amber">hypothetical data</span>`;
  // ---- values used in the notes and questions (all computed) ----
  const D = DM.DOLL, never = D.rows.find((r) => r.key === "never"), cur = D.rows.find((r) => r.key === "current"), former = D.rows.find((r) => r.key === "former");
  const exCur = cur.ihd - never.ihd, exFor = former.ihd - never.ihd, exPct = (100 * exFor) / exCur;
  const C4 = M.s4Calc("coronary"), D4 = M.s4Calc("deaths");
  const PSC = M.PSC.rows;
  // hypothetical cohort for the worked example and calculation questions
  const CO = { sm: { n: 4000, cases: 48 }, no: { n: 6000, cases: 30 }, years: 10 };
  const rS = M.rate(CO.sm.cases, CO.sm.n), rN = M.rate(CO.no.cases, CO.no.n), RR = rS / rN, AD = rS - rN;
  // hypothetical relative v absolute example
  const RA = { base: 4, rr: 1.5 }; const RAnew = RA.base * RA.rr;
  const BP = M.BPCOH.rows; const bpTop = BP[BP.length - 1];
  const TW = M.TOWNS, tp = M.townTot("P"), tq = M.townTot("Q");

  const SOURCES = `<p class="tiny muted"><strong>Sources</strong> (each figure checked on 11 November 2026): ${M.SRC.psc.cite} (<a href="${M.SRC.psc.url}" target="_blank" rel="noopener">record</a>); ${M.SRC.s4.cite} (<a href="${M.SRC.s4.url}" target="_blank" rel="noopener">paper</a>); ${M.SRC.unal.cite} (<a href="${M.SRC.unal.url}" target="_blank" rel="noopener">record</a>); ${DM.SRC.doll.cite} (<a href="${DM.SRC.doll.url}" target="_blank" rel="noopener">paper</a>); ${DM.SRC.lewington.cite} (<a href="${DM.SRC.lewington.url}" target="_blank" rel="noopener">record</a>). Mechanisms: OpenStax <em>Anatomy and Physiology</em> <a href="${M.SRC.openstax.url}" target="_blank" rel="noopener">§19.1</a> (listed risk factors include smoking, family history, hypertension, obesity, diabetes and high cholesterol or lipid levels). Hypothetical datasets are invented for teaching and are labelled wherever they appear.</p>`;

  // ---- Cardiovascular Risk Data Investigator ----
  const inv = { kind: "cvdRiskData", title: "Cardiovascular Risk Data Investigator",
    note: "Four datasets about coronary heart disease: two real (cited) and two hypothetical (labelled). Change the view or split the data, then judge the conclusions. These data describe populations; they cannot tell anyone their own risk.",
    items: [
      { id: "s4", label: "A cholesterol trial", tag: "real", title: "Lowering cholesterol in people with CHD: the 4S randomised trial", intro: `${n0(M.S4.n)} people who already had angina or had had a myocardial infarction, with blood cholesterol of ${M.S4.chol}, were randomly allocated to a cholesterol-lowering drug (simvastatin) or a placebo and followed for a median of ${M.S4.years} years. On the drug, total cholesterol fell by about 25 % and LDL cholesterol by about 35 %.`,
        claims: [
          { s: "In people who already had CHD, lowering blood cholesterol reduced coronary deaths over about five years.", v: "yes", why: "Random allocation makes the groups alike except for the treatment, so the fall from 8.5 % to 5.0 % can be put down to the treatment, which lowered cholesterol. This supports a causal role for cholesterol." },
          { s: "The drug would reduce coronary deaths by about 40 % in healthy teenagers.", v: "no", why: "Everyone in the trial already had CHD and raised cholesterol; the result cannot simply be applied to a very different, low-risk group." },
          { s: `For every 1000 such patients treated for about five years, roughly ${f0(C4.per1000)} fewer died from CHD.`, v: "yes", why: `Absolute risk reduction ${f1(C4.abs)} percentage points = about ${f0(C4.per1000)} per 1000.` },
        ],
        questions: [
          { id: `q-${R}-iv3`, ref: R, stmts: S(2), type: "gap", marks: 1, stem: "Coronary deaths. Use the absolute risk reduction shown (3.5 percentage points). Give your answer as a whole number.", text: "About {{1}} people like those in the trial would need to be treated for about five years to prevent one coronary death.", answers: { 1: [...new Set([f0(100 / C4.abs), f0(100 / M.round(C4.abs, 1)), String(Math.floor(100 / C4.abs))])] }, explanation: `100 ÷ ${f1(C4.abs)} = ${f1(100 / M.round(C4.abs, 1))}, about ${f0(100 / M.round(C4.abs, 1))} people (supporting: this is the 'number needed to treat'). ${f0(100 / C4.abs)} and ${Math.floor(100 / C4.abs)} are also accepted.` },
          { id: `q-${R}-iv4`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "Why does this trial give stronger evidence that lowering cholesterol reduces CHD deaths than a cohort study comparing people with high and low cholesterol?", options: ["Random allocation means other risk factors should be similar in both groups", "The trial included more people than any cohort study", "Trials do not need a control group", "Placebos lower cholesterol"], answer: 0, explanation: "Randomisation balances confounders (known and unknown) between the groups; the placebo group is the control." },
        ] },
      { id: "unal", label: "A national trend", tag: "real", title: "Why did CHD deaths fall in England and Wales between 1981 and 2000?", intro: `Death rates from CHD in England and Wales fell steeply between ${M.UNAL.from} and ${M.UNAL.to}. Researchers used a computer model, combining the trend with evidence from trials and cohort studies, to estimate how much of the fall came from changes in risk factors and how much from medical treatment.`,
        claims: [
          { s: "CHD death rates in England and Wales fell between 1981 and 2000.", v: "yes", why: `A fall of ${M.UNAL.fallMen} % in men and ${M.UNAL.fallWomen} % in women aged ${M.UNAL.ages}, from national statistics.` },
          { s: "The data prove that the fall in smoking caused most of the fall in deaths.", v: "no", why: `Not supported. Even the model's estimate gives the fall in smoking about ${M.UNAL.smokePct} % of the fall in deaths, less than half, and these shares are estimates from a model that depends on its assumptions; a trend alone cannot separate the effects of things that changed together.` },
          { s: "Obesity cannot be a risk factor, because deaths fell while obesity increased.", v: "no", why: "Several factors changed at once. A fall in smoking and better treatment could outweigh the effect of rising obesity; the researchers reported the rises in obesity and diabetes and the fall in physical activity as adverse trends that worked against the fall." },
        ],
        questions: [
          { id: `q-${R}-iv5`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "Why is it difficult to tell from a national trend alone which factor caused a fall in CHD deaths?", options: ["Many factors (smoking, diet, blood pressure, treatment) changed at the same time", "National statistics never record causes of death", "The number of deaths was too small", "A trend always shows causation"], answer: 0, explanation: "Changes that happen together are confounded with each other in a trend." },
          { id: `q-${R}-iv6`, ref: R, stmts: S(2), type: "gap", marks: 1, stem: "Use the chart: the model gave the fall in smoking alone 48 % of the fall in deaths. Give your answer to the nearest 100.", text: `About {{1}} of the ${n0(M.UNAL.fewer)} fewer deaths in 2000 were attributed to the fall in smoking.`, answers: { 1: [n0(Math.round(M.UNAL.fewer * M.UNAL.smokePct / 10000) * 100), String(Math.round(M.UNAL.fewer * M.UNAL.smokePct / 10000) * 100)] }, explanation: `${n0(M.UNAL.fewer)} × ${M.UNAL.smokePct} ÷ 100 = ${n0(Math.round(M.UNAL.fewer * M.UNAL.smokePct / 100))}, about ${n0(Math.round(M.UNAL.fewer * M.UNAL.smokePct / 10000) * 100)}. This is a model estimate, not a count.` },
        ] },
      { id: "bp", label: "Blood pressure cohort", tag: "hyp", title: "Systolic blood pressure and new CHD over 10 years (HYPOTHETICAL cohort)", intro: `HYPOTHETICAL data. ${n0(BP.reduce((a, r) => a + r.n, 0))} adults aged 40 to 69 without CHD had their systolic blood pressure measured and were followed for ${M.BPCOH.years} years. The table counts those who developed CHD in each band.`,
        claims: [
          { s: "The rate of new CHD rises with each higher band of systolic blood pressure.", v: "yes", why: `From ${f1(BP[0].rate)} to ${f1(bpTop.rate)} per 1000: a consistent trend (a dose–response).` },
          { s: "Everyone whose systolic pressure is 180 mmHg or more will develop CHD.", v: "no", why: `${f1(bpTop.free)} % of that band did not develop CHD in 10 years. A risk factor raises the probability; it does not make disease certain.` },
          { s: "The rate for the highest band is as reliable as the rate for the 120–139 band.", v: "no", why: `The highest band has only ${bpTop.n} people and ${bpTop.cases} cases, so a few cases more or fewer change its rate a lot; the 120–139 band has ${n0(BP[1].n)} people.` },
          { s: "These data show that high blood pressure causes CHD.", v: "partly", why: "A strong dose–response in a cohort supports a causal link, but people with high blood pressure may also differ in other ways (age, weight, smoking). Trials of lowering blood pressure and a plausible mechanism are also needed." },
        ],
        questions: [
          { id: `q-${R}-iv9`, ref: R, stmts: S(2), type: "gap", marks: 1, stem: "Compare two bands that the table does not compare for you. Give your answer to 2 decimal places.", text: "Rate in the 180-or-more band ÷ rate in the 120–139 band = {{1}}.", answers: { 1: [...new Set([f2(bpTop.rate / BP[1].rate), f2(M.round(bpTop.rate, 1) / M.round(BP[1].rate, 1))])] }, explanation: `${f1(bpTop.rate)} ÷ ${f1(BP[1].rate)} = ${f2(M.round(bpTop.rate, 1) / M.round(BP[1].rate, 1))} (from the unrounded rates, ${M.fix(bpTop.rate, 3)} ÷ ${M.fix(BP[1].rate, 3)} = ${f2(bpTop.rate / BP[1].rate)}; both are accepted).` },
          { id: `q-${R}-iv10`, ref: R, stmts: S(1, 2), type: "mcq", marks: 1, stem: "Which statement about the 180-or-more band is best supported by the data?", options: [`Most people in it (${f0(bpTop.free)} %) did not develop CHD in 10 years, but their rate was the highest`, "Everyone in it developed CHD", "It gives the most reliable rate because blood pressure was highest", "It shows high blood pressure has no effect"], answer: 0, explanation: `${bpTop.cases} of ${bpTop.n} developed CHD (${f0(bpTop.rate)} per 1000); risk is a probability, not a certainty.` },
        ] },
      { id: "towns", label: "Two towns (stretch)", tag: "hyp", title: "Comparing two towns: crude and age-specific rates (HYPOTHETICAL)", intro: `HYPOTHETICAL data. A health survey counted new cases of CHD over ${TW.years} years among people aged 45 and over in two towns. Town P has many retired people; Town Q has mostly younger families.`,
        claims: [
          { s: "Town P has a higher crude rate of CHD than Town Q.", v: "yes", why: `${f1(M.rate(tp.cases, tp.n))} v ${f1(M.rate(tq.cases, tq.n))} per 1000 with all ages together.` },
          { s: "Living in Town P increases a person's risk of developing CHD.", v: "no", why: "Within each age group Town Q's rate is higher. Town P's higher crude rate is explained by its older population: age is a confounding variable." },
          { s: "To compare the towns fairly, rates should be compared within the same age groups.", v: "yes", why: "Comparing like with like removes the effect of the different age structures (an age-standardised rate does the same in one number)." },
        ],
        questions: [
          { id: `q-${R}-iv7`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "Why does Town P have the higher crude rate even though its age-specific rates are lower?", options: ["A much larger proportion of its population is in the older age group, where CHD is more common", "Town P's data were collected over a longer time", "Town Q's people are all younger than 45", "The crude rate is calculated incorrectly"], answer: 0, explanation: `${f0(M.pct(TW.P.rows[1].n, tp.n))} % of Town P's people are 65 or over, against ${f0(M.pct(TW.Q.rows[1].n, tq.n))} % in Town Q.` },
          { id: `q-${R}-iv8`, ref: R, stmts: S(2), type: "gap", marks: 1, stem: "Split the data. Give your answer to 2 decimal places.", text: "For people aged 65 and over, Town Q's rate ÷ Town P's rate = {{1}}.", answers: { 1: ["1.13", "1.12", "1.125"] }, explanation: `${f1(M.rate(TW.Q.rows[1].cases, TW.Q.rows[1].n))} ÷ ${f1(M.rate(TW.P.rows[1].cases, TW.P.rows[1].n))} = ${M.fix(M.rate(TW.Q.rows[1].cases, TW.Q.rows[1].n) / M.rate(TW.P.rows[1].cases, TW.P.rows[1].n), 3)}, 1.13 to 2 decimal places (1.12 is also accepted, as calculators and rounding rules differ on an exact 5). Within this age group Town Q's rate is higher, the reverse of the crude comparison.` },
        ] },
    ] };

  window.BIO.content[R] = {
    status: "draft",
    keywords: ["risk factor", "coronary heart disease", "CHD", "diet", "saturated fat", "salt", "blood cholesterol", "LDL", "HDL", "cigarette smoking", "carbon monoxide", "nicotine", "high blood pressure", "hypertension", "incidence", "rate", "mortality", "relative risk", "absolute risk", "hazard ratio", "odds ratio", "correlation", "causation", "association", "confounding variable", "cohort study", "case-control study", "randomised controlled trial", "placebo", "sample size", "age-standardised", "dose–response", "trend"],
    notes: () => `
<div class="notice"><strong>What the specification requires (3.2.7.2).</strong> The <strong>risk factors associated with coronary heart disease: diet, blood cholesterol, cigarette smoking and high blood pressure</strong>; and you must be able to <strong>analyse, interpret and evaluate data</strong> associated with specific risk factors and the <strong>incidence</strong> of coronary heart disease. Other risk factors (age, sex, family history, physical inactivity, obesity, diabetes) and the ways each factor acts are supporting. Risk factors in general, and smoking and cancer data, are in <a href="#/topic/3.2.1.2">3.2.1.2</a>. Labels: <span class="badge teal">required</span> <span class="badge">supporting</span> <span class="badge amber">stretch</span> ${REAL} ${HYP}</div>

<h2 data-stmt="${R}.s1 ${R}.s2">1. What a risk factor is <span class="badge teal">required</span></h2>
<p>A <strong>risk factor</strong> is something that is <strong>associated with an increased probability</strong> of developing a disease. Coronary heart disease (CHD) is caused by atheroma in the coronary arteries and the thrombosis it leads to (<a href="#/topic/3.2.7.1">3.2.7.1</a>); risk factors make these more likely.</p>
<ul><li>A risk factor <strong>does not guarantee</strong> disease. Many people with a risk factor never develop CHD, and some people with none do.</li>
<li>Risk is a property of <strong>groups</strong>: it is measured by counting how often disease happens in large numbers of people. It cannot say what will happen to one person.</li>
<li>Some risk factors can be changed (diet, smoking, blood pressure, blood cholesterol); others cannot (age, sex, the genes you inherit; <span class="badge">supporting</span>).</li></ul>
<p><strong>Key words for data.</strong> The <strong>incidence</strong> of a disease is the number of <strong>new cases</strong> in a population in a stated time, usually given as a <strong>rate</strong> (for example new cases per 1000 people per year) so that groups of different sizes can be compared. <strong>Mortality</strong> is the number of deaths. <strong>Absolute risk</strong> is the chance of the disease in a group (for example 12 per 1000); <strong>relative risk</strong> compares two groups (rate in one ÷ rate in the other).</p>

<h2 data-stmt="${R}.s1">2. Diet <span class="badge teal">required</span></h2>
<p>Diet affects CHD risk mainly through its effects on <strong>blood cholesterol</strong> and <strong>blood pressure</strong>, and through body mass:</p>
<ul><li>A diet high in <strong>saturated fat</strong> raises the concentration of cholesterol carried in <strong>low-density lipoproteins (LDL)</strong> in the blood, so more lipid can build up in artery walls as atheroma. <span class="badge">supporting</span> Replacing saturated fat with unsaturated fat lowers LDL cholesterol; trans fats (in some processed foods) raise it.</li>
<li>A diet high in <strong>salt</strong> raises <strong>blood pressure</strong> in many people.</li>
<li>Eating more energy than is used leads to <strong>obesity</strong>, which is associated with high blood pressure, high blood cholesterol and diabetes (<span class="badge">supporting</span>).</li>
<li>Diets with plenty of fruit, vegetables and fibre are <strong>associated</strong> with a lower risk.</li></ul>
<p>Diet is hard to study: people eat many foods, report what they eat inaccurately, and people with healthy diets often differ in other ways too (they may smoke less and exercise more). Diet data therefore need especially careful evaluation (section 8).</p>

<h2 data-stmt="${R}.s1">3. Blood cholesterol <span class="badge teal">required</span></h2>
<p>Cholesterol is a lipid. It is insoluble in water, so it is carried in the blood in <strong>lipoproteins</strong> (lipid with protein). A high concentration of <strong>blood cholesterol</strong> is associated with more atheroma and a higher risk of CHD.</p>
<ul><li><span class="badge">supporting</span> <strong>LDL</strong> (low-density lipoprotein) carries cholesterol to body cells; high LDL is associated with more cholesterol entering and staying in artery walls. <strong>HDL</strong> (high-density lipoprotein) carries cholesterol away from tissues to the liver; higher HDL is associated with a lower risk. The ratio of total to HDL cholesterol predicts CHD better than total cholesterol alone.</li>
<li>Blood cholesterol depends on <strong>diet</strong> (especially saturated fat) and on <strong>inherited</strong> factors (<span class="badge">supporting</span>).</li></ul>
<p><strong>Evidence from cohort studies</strong> ${REAL}. In ${M.PSC.studies} cohort studies of ${M.PSC.adults} adults, a 1 mmol/L lower usual total cholesterol was associated with a lower death rate from ischaemic heart disease (CHD) at every age: ${PSC.map((r) => `hazard ratio ${f2(r.hr)} at ${r.age}`).join(", ")} (${link("psc")}).</p>
<p><strong>Evidence from a trial</strong> ${REAL}. In the 4S trial, ${n0(M.S4.n)} people with CHD were randomly given a cholesterol-lowering drug or a placebo. Over a median of ${M.S4.years} years, ${f1(C4.p)} % of the placebo group and ${f1(C4.s)} % of the treated group died from CHD (${link("s4")}). Because the groups were allocated at random, this is strong evidence that lowering cholesterol <em>causes</em> fewer coronary deaths, in people like those in the trial.</p>

<h2 data-stmt="${R}.s1">4. Cigarette smoking <span class="badge teal">required</span></h2>
<p>Smoking is one of the strongest risk factors for CHD that can be changed. <span class="badge">supporting</span> Several substances in tobacco smoke are involved:</p>
<ul><li><strong>Carbon monoxide</strong> combines with haemoglobin (<a href="#/topic/3.1.5.3">3.1.5.3</a>), so the blood carries less oxygen; the heart muscle must work harder with less oxygen.</li>
<li><strong>Nicotine</strong> raises heart rate and blood pressure, narrows arteries and makes <strong>platelets stickier</strong>, so thrombosis is more likely.</li>
<li>Other chemicals <strong>damage the endothelium</strong>, which starts atheroma.</li></ul>
<p><strong>Evidence</strong> ${REAL}. In 50 years of follow-up of British male doctors, the death rate from ischaemic heart disease was ${f2(never.ihd)} per 1000 men per year in lifelong non-smokers, ${f2(former.ihd)} in former smokers and ${f2(cur.ihd)} in current cigarette smokers (age-standardised; ${link("doll", DM.SRC)}). These data are analysed in the Risk Factor Data Investigator in <a href="#/topic/3.2.1.2">3.2.1.2</a>.</p>

<h2 data-stmt="${R}.s1">5. High blood pressure <span class="badge teal">required</span></h2>
<p>High blood pressure (hypertension) is associated with a higher risk of CHD. <span class="badge">supporting</span> It acts in several ways:</p>
<ul><li>It <strong>damages the endothelium</strong> of arteries, which makes atheroma more likely to form.</li>
<li>It puts more strain on artery walls, so a wall weakened by atheroma is more likely to form an <strong>aneurysm</strong> (<a href="#/topic/3.2.7.1">3.2.7.1</a>).</li>
<li>The heart must pump against a higher pressure, so the heart muscle needs more oxygen.</li></ul>
<p>Blood pressure is raised by a diet high in salt, obesity, physical inactivity, excess alcohol and stress (<span class="badge">supporting</span>); it also rises with age.</p>
<p><strong>Evidence</strong> ${REAL}. ${DM.LEWINGTON.statement} (${link("lewington", DM.SRC)}).</p>

<h2 data-stmt="${R}.s1">6. Risk factors act together <span class="badge teal">required</span></h2>
<p>The four factors are linked: diet affects blood cholesterol and blood pressure, and smoking raises blood pressure. Their effects <strong>add up</strong>: a person with several risk factors has a much higher risk than a person with one. The diagram below shows how each factor is linked to atheroma, thrombosis and myocardial infarction.</p>
<p><span class="badge">supporting</span> Other risk factors: <strong>age</strong> (risk rises steeply with age), <strong>sex</strong> (men tend to develop CHD at younger ages), <strong>family history and inherited factors</strong>, <strong>physical inactivity</strong>, <strong>obesity</strong> and <strong>diabetes</strong>. Age and sex matter when you compare groups: a group of older people will have more CHD whatever else is true.</p>

<h2 data-stmt="${R}.s2">7. Interpreting risk data <span class="badge teal">required</span></h2>
<p><strong>Calculate rates before comparing.</strong> ${HYP} In a cohort followed for ${CO.years} years, ${CO.sm.cases} of ${n0(CO.sm.n)} smokers and ${CO.no.cases} of ${n0(CO.no.n)} non-smokers developed CHD. The raw numbers (${CO.sm.cases} and ${CO.no.cases}) mislead because the groups are different sizes. Rates: smokers ${CO.sm.cases} ÷ ${n0(CO.sm.n)} × 1000 = <strong>${f0(rS)} per 1000</strong>; non-smokers ${CO.no.cases} ÷ ${n0(CO.no.n)} × 1000 = <strong>${f0(rN)} per 1000</strong>.</p>
<ul><li><strong>Relative risk</strong> = ${f0(rS)} ÷ ${f0(rN)} = <strong>${f1(RR)}</strong>: smokers had ${f1(RR)} times the rate. A relative risk of 1 means no difference.</li>
<li><strong>Absolute difference</strong> = ${f0(rS)} − ${f0(rN)} = <strong>${f0(AD)} extra cases per 1000</strong> people over ${CO.years} years.</li></ul>
<p><strong>Relative and absolute risk tell different stories.</strong> ${HYP} If a factor raises risk by 50 % (relative risk ${f1(RA.rr)}) when the baseline risk is ${RA.base} in 1000, the risk becomes ${f0(RAnew)} in 1000: only ${f0(RAnew - RA.base)} extra cases per 1000. Headlines often quote the relative change because it sounds larger. Always ask: <em>out of how many?</em> The real 4S trial results show the same thing: a relative reduction in coronary deaths of about ${f0(C4.relRed)} % was an absolute reduction of ${f1(C4.abs)} percentage points, about ${f0(C4.per1000)} fewer deaths per 1000 people treated for five years.</p>
<p><strong>Other measures you may meet.</strong> A <strong>hazard ratio</strong> (cohort studies) and an <strong>odds ratio</strong> (case-control studies) are read like a relative risk: 1 = no difference; above 1 = higher risk in the group with the factor; below 1 = lower. A <strong>confidence interval</strong> shows the range within which the true value probably lies; if it does not include 1, the difference is unlikely to be due to chance alone. <span class="badge">supporting</span></p>
<p><strong>Describe graphs precisely</strong>: give the trend, quote values with units, and compare using calculations (for example "the rate rises from ${f1(BP[0].rate)} to ${f1(bpTop.rate)} per 1000"). A <strong>correlation</strong> means two variables change together; it does not show that one causes the other.</p>

<h2 data-stmt="${R}.s2">8. Evaluating risk data <span class="badge teal">required</span></h2>
<p>When you evaluate data about a risk factor and CHD, work through these questions:</p>
${tbl([
  ["Association or cause?", "A link (correlation) between a factor and CHD does not show that the factor causes CHD. Evidence for cause builds up when the link is strong, found in many studies, shows a dose–response (more exposure, more disease), comes before the disease, has a plausible mechanism, and when removing the factor in a trial lowers the risk."],
  ["Confounding variables?", "A confounding variable is linked to both the factor and the disease, so it can create or hide an association. Age, sex, smoking, income and other habits are common confounders. Good studies compare like with like or adjust for them."],
  ["What kind of study?", "<strong>Cohort</strong>: follows people with and without a factor forward in time and counts new cases. <strong>Case-control</strong>: compares the past exposures of people with and without the disease. <strong>Randomised controlled trial</strong>: allocates the factor or treatment at random, so confounders are balanced; strongest evidence of cause. <strong>Ecological</strong>: compares whole countries or towns; cannot show what happens to individuals."],
  ["How large and representative?", "Small samples give unreliable rates (a few cases change the result a lot). Who was studied (age, sex, country, already ill?) limits who the results apply to."],
  ["How was it measured?", "Self-reported diet or smoking may be inaccurate; was CHD diagnosed in the same way in every group?"],
  ["Is the trend reliable?", "Are there enough data points and people in each group? Did other things change at the same time? Is the change larger than the variation you would expect?"],
  ["Relative or absolute?", "Is the size of the effect given in absolute terms, so you can tell how many people are affected?"],
], ["Ask", "Why it matters"])}
<p>Use the investigator to practise on real and hypothetical data: absolute and relative risk in a trial, association and cause in a national trend, rates and sample size in a blood pressure study and, as stretch, a confounding variable.</p>

<h2 data-stmt="${R}.s1 ${R}.s2">9. Common misconceptions <span class="badge teal">required</span></h2>
<ul><li><strong>"A risk factor causes the disease."</strong> It is associated with a higher probability. Many people with a risk factor never develop CHD.</li>
<li><strong>"If I have no risk factors I cannot get CHD."</strong> Risk is lower, not zero; age and inherited factors also matter.</li>
<li><strong>"More cases means a higher risk."</strong> Only if the groups are the same size and observed for the same time. Compare rates.</li>
<li><strong>"A 50 % increase in risk means half the people get the disease."</strong> It means the risk is 1.5 times the baseline; if the baseline is small, the extra risk is small.</li>
<li><strong>"A correlation proves cause."</strong> Confounding variables or chance can produce a correlation.</li>
<li><strong>"All fat in the diet raises cholesterol equally."</strong> Saturated fat is the main dietary influence on LDL cholesterol; unsaturated fats do not raise it in the same way (supporting).</li>
<li><strong>"A study of one group applies to everyone."</strong> Results from middle-aged men with CHD may not apply to young women without it.</li></ul>
${SOURCES}`,
    diagrams: [
      { id: `d-${R}-1`, title: "How the four risk factors are linked to coronary heart disease", status: "draft", caption: "Each of the four specified risk factors makes atheroma in coronary arteries more likely; atheroma in turn makes thrombosis and an aneurysm more likely, and a thrombus in a coronary artery causes a myocardial infarction. Smoking also makes platelets stickier, so thrombosis is more likely. Every arrow means 'more likely', not 'certain'. The mechanisms in the boxes are supporting.", alt: "Concept diagram. Four boxes along the top: Diet (saturated fat raises LDL cholesterol; salt raises blood pressure), Blood cholesterol (high LDL: more lipid enters and stays in artery walls), Smoking (damages endothelium; carbon monoxide carried by haemoglobin; stickier platelets) and High blood pressure (damages endothelium; strains weakened artery walls). Arrows from all four lead to a central box: Atheroma in coronary artery walls (lumen narrows; wall roughened and weakened). From it arrows lead to Aneurysm (weakened wall bulges, worse with high blood pressure; may burst) and Thrombosis (blood clot forms on the atheroma and blocks a coronary artery). A dashed arrow from Smoking to Thrombosis is labelled stickier platelets. Thrombosis leads to Myocardial infarction. A note says each arrow means more likely, not certain.", svg: A.riskWeb() },
    ],
    interactives: [inv],
    focus: [
      { slot: "atheroma-openstax", title: "From a plaque to a population", ref: R, caption: "The plaque in this coronary artery is what CHD risk factors make more likely. Researchers cannot watch plaques grow in thousands of people, so they count heart attacks and deaths in large groups instead.", explanation: () => `<p>How do we know that blood cholesterol matters? The first clues were observational: from the middle of the twentieth century, cohort studies followed thousands of people and found that those with higher blood cholesterol developed CHD more often. But people with high cholesterol might differ in other ways, so an association was not enough. The decisive test came from randomised controlled trials. In the 4S trial (1994), ${n0(M.S4.n)} people who already had CHD were allocated at random to a cholesterol-lowering drug or a placebo; over about five years, coronary deaths fell from ${f1(C4.p)} % to ${f1(C4.s)} %. Random allocation made the two groups alike except for the treatment, so the difference could be put down to lowering cholesterol. Later, a combined analysis of ${M.PSC.studies} cohort studies of ${M.PSC.adults} adults showed that the association with lower cholesterol held at every age from 40 to 89. Notice the different strengths of evidence: cohorts show an association and its size; trials test cause.</p>${SOURCES}`,
        question: { id: `q-${R}-fx1`, ref: R, stmts: S(1, 2), type: "short", marks: 3, stem: "Explain why the 4S randomised trial gave stronger evidence than earlier cohort studies that blood cholesterol is a cause of CHD, and give one limitation of the trial's result. (3 marks)", scheme: [{ point: "In cohort studies people with high cholesterol may differ in other ways (confounding variables), so only an association is shown", marks: 1 }, { point: "Random allocation makes the groups similar in other risk factors / the only systematic difference is the treatment (placebo control)", marks: 1 }, { point: "Limitation: participants already had CHD (and raised cholesterol), so the result may not apply to other people / the drug may have other effects besides lowering cholesterol", marks: 1 }], model: "In a cohort study, people with high blood cholesterol may also differ in other ways, such as diet, smoking or weight, so these confounding variables could explain the link and only an association is shown. In the trial, people were allocated at random to the drug or to a placebo, so the two groups should be similar in every other risk factor and the only systematic difference was the treatment that lowered cholesterol; the fall in coronary deaths can therefore be put down to lowering cholesterol. A limitation is that everyone in the trial already had CHD and raised cholesterol, so the result may not apply to healthy people or people with normal cholesterol.", commonErrors: "Saying the trial was bigger (it was smaller than many cohorts)." } },
    ],
    examFocus: `<ul>
<li><strong>Name the four.</strong> Diet, blood cholesterol, cigarette smoking, high blood pressure. Others (age, sex, inheritance, inactivity, obesity, diabetes) are supporting.</li>
<li><strong>Explain a risk factor</strong> by linking it to the biology: e.g. high blood pressure damages the endothelium, so atheroma is more likely; smoking makes platelets stickier, so thrombosis is more likely; saturated fat raises LDL cholesterol.</li>
<li><strong>Use "associated with", "increases the risk of", "more likely".</strong> Never write that a risk factor "causes" or "will give" CHD unless the data are from a trial and the question asks about cause.</li>
<li><strong>Calculations.</strong> Convert counts to rates (cases ÷ people × 1000); relative risk = rate with factor ÷ rate without; absolute difference = rate with − rate without; percentage change = change ÷ original × 100. Show working and units ("per 1000 per year").</li>
<li><strong>Evaluate in points.</strong> Correlation not cause; named confounders; study type; sample size and who was studied; how variables were measured; relative v absolute; whether the trend is consistent. Each point must be tied to the data in front of you.</li>
<li><strong>Describe data</strong> with the trend plus two quoted values with units, then a comparison.</li>
<li><strong>Common mistakes.</strong> Comparing raw numbers of cases from groups of different sizes; calling a correlation proof; assuming results from one group apply to everyone; reading a relative risk as a percentage of people affected.</li></ul>`,
    synoptic: [
      { ref: "3.2.7.1", text: "What the risk factors act on: atheroma, thrombosis, aneurysm and myocardial infarction." },
      { ref: "3.2.1.2", text: "Risk factors for CHD and cancer, lifestyle change, and the analysis of risk data (including the British doctors smoking data)." },
      { ref: "3.1.1.3", text: "Lipids: saturated and unsaturated fatty acids; cholesterol is a lipid carried in lipoproteins." },
      { ref: "3.1.5.3", text: "Carbon monoxide from smoke combines with haemoglobin, reducing the oxygen carried." },
      { ref: "3.1.6", text: "Variation, sampling and the reliability of data: sample size, mean and spread." },
      { ref: "3.2.6.1", text: "Blood pressure in arteries; the endothelium lining blood vessels." },
    ],
    quickCheck: [
      { id: `q-${R}-qc1`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "Which is one of the four risk factors for CHD named in the specification?", options: ["High blood pressure", "Low blood pressure", "A diet high in fibre", "Blood group O"], answer: 0, explanation: "The four are diet, blood cholesterol, cigarette smoking and high blood pressure." },
      { id: `q-${R}-qc2`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "What does it mean to say smoking is a risk factor for CHD?", options: ["Smokers are more likely to develop CHD than non-smokers", "Every smoker will develop CHD", "Only smokers develop CHD", "Smoking is the only cause of CHD"], answer: 0, explanation: "A risk factor increases the probability; it does not guarantee disease." },
      { id: `q-${R}-qc3`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: `${HYP} Group X: 30 new CHD cases among 2000 people. Group Y: 30 cases among 6000 people, over the same time. Which is correct?`, options: ["The rate in X is three times the rate in Y", "The risk is the same, because the number of cases is the same", "The rate in Y is three times the rate in X", "No comparison is possible"], answer: 0, explanation: "X: 15 per 1000; Y: 5 per 1000; 15 ÷ 5 = 3." },
      { id: `q-${R}-qc4`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "A study finds that people who drink more coffee have more CHD. Smokers drink more coffee than non-smokers. What is smoking in this study?", options: ["A possible confounding variable", "The dependent variable", "Proof that coffee causes CHD", "The control group"], answer: 0, explanation: "Smoking is linked to both coffee drinking and CHD, so it could explain the association." },
      { id: `q-${R}-qc5`, ref: R, stmts: S(1), type: "gap", marks: 1, stem: "Complete the sentence.", text: "A diet high in saturated fat raises the concentration of {{1}} in the blood.", answers: { 1: ["cholesterol", "LDL", "LDL cholesterol", "low-density lipoprotein", "blood cholesterol"] }, explanation: "Saturated fat raises (LDL) cholesterol, which is associated with more atheroma." },
    ],
    flashcards: [
      { id: `f-${R}-1`, front: "The four risk factors for CHD named in the specification.", back: "Diet, blood cholesterol, cigarette smoking and high blood pressure." },
      { id: `f-${R}-2`, front: "Risk factor (definition).", back: "Something associated with an increased probability of developing a disease; it does not guarantee the disease." },
      { id: `f-${R}-3`, front: "How does diet affect CHD risk?", back: "Saturated fat raises LDL cholesterol; salt raises blood pressure; excess energy leads to obesity." },
      { id: `f-${R}-4`, front: "How is high blood cholesterol linked to CHD?", back: "Associated with more lipid building up in artery walls, so more atheroma in coronary arteries." },
      { id: `f-${R}-5`, front: "LDL and HDL (supporting).", back: "LDL carries cholesterol to cells; high LDL linked with more atheroma. HDL carries cholesterol to the liver; higher HDL linked with lower risk." },
      { id: `f-${R}-6`, front: "Three ways smoking increases CHD risk (supporting).", back: "Chemicals damage the endothelium (atheroma); carbon monoxide combines with haemoglobin (less oxygen); nicotine raises blood pressure and makes platelets stickier (thrombosis)." },
      { id: `f-${R}-7`, front: "How does high blood pressure increase CHD risk (supporting)?", back: "Damages the endothelium, so atheroma is more likely; strains weakened walls (aneurysm); the heart must work harder." },
      { id: `f-${R}-8`, front: "Supporting risk factors for CHD.", back: "Age, sex, family history and inherited factors, physical inactivity, obesity, diabetes." },
      { id: `f-${R}-9`, front: "Incidence.", back: "The number of new cases of a disease in a population in a stated time, usually as a rate (e.g. per 1000 per year)." },
      { id: `f-${R}-10`, front: "Why calculate rates before comparing groups?", back: "Groups differ in size (and time observed); rate = cases ÷ people × 1000 allows a fair comparison." },
      { id: `f-${R}-11`, front: "Relative risk.", back: "Rate in the group with the factor ÷ rate in the group without it; 1 = no difference." },
      { id: `f-${R}-12`, front: "Absolute risk difference.", back: "Rate with the factor − rate without, e.g. 7 extra cases per 1000 people over 10 years." },
      { id: `f-${R}-13`, front: "Why can a large relative risk be a small absolute risk?", back: "If the baseline risk is low, multiplying it still gives a small number: 1.5 × 4 per 1000 = 6 per 1000, only 2 extra." },
      { id: `f-${R}-14`, front: "Confounding variable.", back: "A variable linked to both the risk factor and the disease, which can create or hide an apparent association (e.g. age, smoking)." },
      { id: `f-${R}-15`, front: "Correlation v causation.", back: "A correlation shows two variables change together; it does not show that one causes the other." },
      { id: `f-${R}-16`, front: "Cohort, case-control, randomised controlled trial.", back: "Cohort: follow forward and count new cases. Case-control: compare past exposures of people with and without the disease. RCT: random allocation; strongest test of cause." },
      { id: `f-${R}-17`, front: "Why do randomised trials give strong evidence of cause?", back: "Random allocation balances other risk factors between groups, so a difference in outcome can be put down to the treatment." },
      { id: `f-${R}-18`, front: "Why is a rate from a small group unreliable?", back: "A few cases more or fewer change it a lot; chance has a large effect." },
      { id: `f-${R}-19`, front: "Hazard ratio or odds ratio of 0.66.", back: "The group with the factor had about two-thirds of the rate (odds): 34 % lower. 1 = no difference." },
      { id: `f-${R}-20`, front: "Evidence that builds a case for cause.", back: "Strong, consistent association; dose–response; exposure before disease; plausible mechanism; risk falls when the factor is removed (trial)." },
      { id: `f-${R}-21`, front: "Why are diet data hard to interpret?", back: "Self-reported intake is inaccurate; foods are eaten together; people with healthy diets often differ in other ways (confounding)." },
    ],
    questions: [
      // ---- MCQ ----
      { id: `q-${R}-m1`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "How does a diet high in saturated fat increase the risk of CHD?", options: ["It raises blood LDL cholesterol, so more atheroma forms in artery walls", "It lowers blood pressure", "It increases the oxygen carried by haemoglobin", "It makes the endothelium thicker and stronger"], answer: 0, explanation: "Saturated fat raises LDL cholesterol, which is associated with more atheroma." },
      { id: `q-${R}-m2`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "Carbon monoxide in tobacco smoke increases the risk of heart disease mainly because it (supporting)", options: ["combines with haemoglobin, reducing the oxygen carried to the heart muscle", "dissolves atheroma", "lowers heart rate", "makes platelets less sticky"], answer: 0, explanation: "Carbon monoxide binds to haemoglobin, so less oxygen is carried." },
      { id: `q-${R}-m3`, ref: R, stmts: S(1), type: "mcq", marks: 1, stem: "Which explains how high blood pressure increases the risk of CHD? (supporting)", options: ["It damages the endothelium of arteries, making atheroma more likely", "It lowers blood cholesterol", "It widens the coronary arteries", "It reduces the work done by the heart"], answer: 0, explanation: "Damage to the lining is an early step in atheroma; high pressure also strains weakened walls." },
      { id: `q-${R}-m4`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "What is the incidence of a disease?", options: ["The number of new cases in a population in a stated time", "The total number of people who have ever had it", "The number of deaths it causes each year", "The chance that one particular person will get it"], answer: 0, explanation: "Incidence counts new cases; it is usually given as a rate." },
      { id: `q-${R}-m5`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: `${HYP} The CHD rate is 8 per 1000 in people with a risk factor and 4 per 1000 in people without it. Which statement is correct?`, options: ["Relative risk 2; absolute difference 4 per 1000", "Relative risk 4; absolute difference 2 per 1000", "Relative risk 2; 50 % of people with the factor develop CHD", "Relative risk 0.5; absolute difference 4 per 1000"], answer: 0, explanation: "8 ÷ 4 = 2; 8 − 4 = 4 extra cases per 1000. 99.2 % of people with the factor did not develop CHD." },
      { id: `q-${R}-m6`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "Which type of study gives the strongest evidence that changing a factor reduces the risk of CHD?", options: ["A randomised controlled trial", "A comparison of CHD rates between countries", "A survey of people who have had a heart attack", "A study of one family"], answer: 0, explanation: "Random allocation balances confounding variables." },
      { id: `q-${R}-m7`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: "Across countries, average salt intake correlates positively with CHD death rates. Which conclusion is justified?", options: ["Salt intake and CHD deaths are associated at the level of countries", "Each person who eats more salt will develop CHD", "Salt is the only cause of CHD", "Reducing salt will remove CHD"], answer: 0, explanation: "An ecological correlation shows an association between countries; it cannot show cause or what happens to individuals, and countries differ in many ways." },
      { id: `q-${R}-m8`, ref: R, stmts: S(2), type: "mcq", marks: 1, stem: `${HYP} A study reports a hazard ratio of 1.00 (95 % confidence interval 0.80 to 1.25) for CHD in people who eat eggs daily. What does this show?`, options: ["No clear difference in CHD rate between the groups", "Eating eggs doubles the risk", "Eating eggs halves the risk", "Eating eggs causes CHD in 25 % of people"], answer: 0, explanation: "1 means no difference, and the interval includes 1." },
      // ---- gap, match ----
      { id: `q-${R}-g1`, ref: R, stmts: S(1), type: "gap", marks: 3, stem: "Complete the passage about the four specified risk factors.", text: "The risk factors for CHD named in the specification are diet, blood {{1}}, cigarette {{2}} and high blood {{3}}.", answers: { 1: ["cholesterol"], 2: ["smoking"], 3: ["pressure"] }, explanation: "Diet, blood cholesterol, cigarette smoking and high blood pressure." },
      { id: `q-${R}-mt1`, ref: R, stmts: S(2), type: "match", marks: 5, stem: "Match each term to its meaning.", pairs: [{ left: "Incidence", right: "Number of new cases in a population in a stated time" }, { left: "Relative risk", right: "Rate with the factor divided by rate without it" }, { left: "Absolute risk difference", right: "Rate with the factor minus rate without it" }, { left: "Confounding variable", right: "A variable linked to both the factor and the disease" }, { left: "Randomised controlled trial", right: "Participants allocated to treatment or control by chance" }] },
      // ---- short, calculation, data, evaluation ----
      { id: `q-${R}-s1`, ref: R, stmts: S(1), type: "short", marks: 3, stem: "Explain how cigarette smoking increases the risk of a myocardial infarction. (3 marks)", scheme: [{ point: "Chemicals damage the endothelium, so atheroma is more likely to form", marks: 1 }, { point: "Nicotine makes platelets stickier / raises blood pressure, so thrombosis (a clot) on an atheroma is more likely", marks: 1 }, { point: "Carbon monoxide combines with haemoglobin so less oxygen reaches cardiac muscle / a thrombus blocks a coronary artery so muscle is starved of oxygen", marks: 1 }], model: "Chemicals in tobacco smoke damage the endothelium of arteries, so atheroma is more likely to build up in the coronary arteries. Nicotine raises blood pressure and makes platelets stickier, so a blood clot is more likely to form on an atheroma and block a coronary artery. Carbon monoxide combines with haemoglobin, so the blood carries less oxygen to the cardiac muscle. All of these make it more likely that part of the heart muscle is starved of oxygen.", commonErrors: "Saying tar blocks the arteries." },
      { id: `q-${R}-c1`, ref: R, stmts: S(2), type: "short", marks: 3, stem: `${HYP} In a cohort followed for ${CO.years} years, ${CO.sm.cases} of ${n0(CO.sm.n)} smokers and ${CO.no.cases} of ${n0(CO.no.n)} non-smokers developed CHD. (a) Calculate the rate per 1000 for each group. (1 mark) (b) Calculate the relative risk for smokers. (1 mark) (c) Calculate how many extra cases per 1000 people were associated with smoking. (1 mark)`, scheme: [{ point: `(a) Smokers ${f0(rS)} per 1000; non-smokers ${f0(rN)} per 1000`, marks: 1 }, { point: `(b) ${f0(rS)} ÷ ${f0(rN)} = ${f1(RR)}`, marks: 1 }, { point: `(c) ${f0(rS)} − ${f0(rN)} = ${f0(AD)} per 1000 (over ${CO.years} years)`, marks: 1 }], model: `(a) Smokers: ${CO.sm.cases} ÷ ${n0(CO.sm.n)} × 1000 = ${f0(rS)} per 1000; non-smokers: ${CO.no.cases} ÷ ${n0(CO.no.n)} × 1000 = ${f0(rN)} per 1000. (b) Relative risk = ${f0(rS)} ÷ ${f0(rN)} = ${f1(RR)}. (c) Extra cases = ${f0(rS)} − ${f0(rN)} = ${f0(AD)} per 1000 people over ${CO.years} years.`, commonErrors: `Comparing ${CO.sm.cases} with ${CO.no.cases} directly.` },
      { id: `q-${R}-c2`, ref: R, stmts: S(1, 2), type: "short", marks: 3, stem: `Data ${REAL}. British male doctors, death rate from ischaemic heart disease per 1000 men per year (age-standardised, 1951–2001): lifelong non-smokers ${f2(never.ihd)}; former smokers ${f2(former.ihd)}; current smokers ${f2(cur.ihd)}. (a) Calculate the excess death rate (above non-smokers) for current smokers and for former smokers. (1 mark) (b) Calculate the former smokers' excess as a percentage of the current smokers' excess. (1 mark) (c) Suggest one reason why these data do not prove that stopping smoking reduces risk by this much. (1 mark)`, scheme: [{ point: `(a) Current ${f2(cur.ihd)} − ${f2(never.ihd)} = ${f2(exCur)}; former ${f2(former.ihd)} − ${f2(never.ihd)} = ${f2(exFor)} per 1000 per year`, marks: 1 }, { point: `(b) ${f2(exFor)} ÷ ${f2(exCur)} × 100 = ${f0(exPct)} % (accept ${f1(exPct)} %)`, marks: 1 }, { point: "(c) Observational: former smokers may differ in other ways (healthier habits, or some stopped because they were already ill); they stopped at different ages and had smoked different amounts; only male doctors studied", marks: 1 }], model: `(a) Current smokers: ${f2(cur.ihd)} − ${f2(never.ihd)} = ${f2(exCur)} extra deaths per 1000 per year; former smokers: ${f2(former.ihd)} − ${f2(never.ihd)} = ${f2(exFor)}. (b) ${f2(exFor)} ÷ ${f2(exCur)} × 100 = ${f0(exPct)} %. (c) This is an observational study: people who stop smoking may differ from those who carry on, for example by adopting other healthier habits, or some may have stopped because they were already ill, so the comparison is confounded; they also stopped at different ages.`, commonErrors: "Dividing the rates instead of the excesses." },
      { id: `q-${R}-d1`, ref: R, stmts: S(2), type: "short", marks: 4, stem: `Data ${REAL}. In ${M.PSC.studies} cohort studies of ${M.PSC.adults} adults, the hazard ratio for death from ischaemic heart disease per 1 mmol/L lower usual total cholesterol was ${PSC.map((r) => `${f2(r.hr)} (95 % confidence interval ${f2(r.lo)}–${f2(r.hi)}) at ages ${r.age}`).join("; ")}. (a) Describe what the data show. (2 marks) (b) Explain why the confidence intervals are so narrow. (1 mark) (c) Give one reason why these data alone do not show that cholesterol causes CHD. (1 mark)`, scheme: [{ point: "(a) Lower cholesterol associated with a lower IHD death rate at every age (all hazard ratios below 1)", marks: 1 }, { point: `(a) Association strongest in middle age and weaker with age: ${f0(100 * (1 - PSC[0].hr))} % lower at 40–49, ${f0(100 * (1 - PSC[1].hr))} % at 50–69, ${f0(100 * (1 - PSC[2].hr))} % at 70–89`, marks: 1 }, { point: "(b) Very large number of people / deaths, so the estimate is precise", marks: 1 }, { point: "(c) Observational (cohort) data: confounding variables (e.g. diet, smoking, weight) may explain part of the association / no intervention", marks: 1 }], model: `(a) At every age, people with lower usual cholesterol had lower death rates from ischaemic heart disease, since all three hazard ratios are below 1 and none of the intervals includes 1. The association is strongest in middle age and weakens with age: a 1 mmol/L lower cholesterol was associated with a ${f0(100 * (1 - PSC[0].hr))} % lower rate at 40–49, ${f0(100 * (1 - PSC[1].hr))} % at 50–69 and ${f0(100 * (1 - PSC[2].hr))} % at 70–89. (b) The intervals are narrow because the analysis included ${M.PSC.adults} people and tens of thousands of deaths, so chance has very little effect on the estimate. (c) These are observational data: people with lower cholesterol may differ in other ways, such as diet, weight or smoking, which could explain part of the association; cause needs evidence such as a trial in which cholesterol is lowered.`, commonErrors: "Reading 0.44 as '44 % lower'." },
      { id: `q-${R}-d2`, ref: R, stmts: S(2), type: "short", marks: 3, stem: `Data ${REAL}. In the 4S trial, ${M.S4.placebo.coronary} of ${n0(M.S4.placebo.n)} people given a placebo and ${M.S4.simva.coronary} of ${n0(M.S4.simva.n)} people given a cholesterol-lowering drug died of CHD over a median of ${M.S4.years} years. (a) Calculate the percentage of each group who died of CHD. (1 mark) (b) Calculate the absolute risk reduction and the relative risk reduction. (2 marks)`, scheme: [{ point: `(a) Placebo ${f1(C4.p)} %; drug ${f1(C4.s)} %`, marks: 1 }, { point: `(b) Absolute: ${f1(C4.p)} − ${f1(C4.s)} = ${f1(C4.abs)} percentage points (about ${f0(C4.per1000)} per 1000)`, marks: 1 }, { point: `(b) Relative: ${f1(C4.abs)} ÷ ${f1(C4.p)} × 100 = ${f0(C4.relRed)} % (accept ${f0(C4.relRed - 1)}–${f0(C4.relRed + 1)} %)`, marks: 1 }], model: `(a) Placebo: ${M.S4.placebo.coronary} ÷ ${n0(M.S4.placebo.n)} × 100 = ${f1(C4.p)} %; drug: ${M.S4.simva.coronary} ÷ ${n0(M.S4.simva.n)} × 100 = ${f1(C4.s)} %. (b) Absolute risk reduction = ${f1(C4.p)} − ${f1(C4.s)} = ${f1(C4.abs)} percentage points, about ${f0(C4.per1000)} fewer deaths per 1000 people treated. Relative risk reduction = ${f1(C4.abs)} ÷ ${f1(C4.p)} × 100 = ${f0(C4.relRed)} %. (The published relative risk, 0.58, comes from an analysis that also uses when each death happened.)`, commonErrors: "Subtracting the numbers of deaths instead of percentages; confusing the two reductions." },
      { id: `q-${R}-d3`, ref: R, stmts: S(2), type: "short", marks: 4, stem: `Data ${HYP}. ${tbl(BP.map((r) => [r.band, n0(r.n), String(r.cases), f1(r.rate)]), ["Systolic blood pressure / mmHg", "People", "New CHD cases in 10 years", "Rate per 1000"])}A student concludes: "High blood pressure causes CHD, and people with a systolic pressure of 180 or more will get it." Evaluate this conclusion. (4 marks)`, scheme: [{ point: `Supports an association: rate rises consistently with each band (${f1(BP[0].rate)} to ${f1(bpTop.rate)} per 1000), a dose–response`, marks: 1 }, { point: "Correlation / cohort data do not prove cause: confounding variables (age, obesity, smoking) not controlled", marks: 1 }, { point: `Most people in the top band did not get CHD: ${bpTop.n - bpTop.cases} of ${bpTop.n} (${f0(bpTop.free)} %); risk is a probability`, marks: 1 }, { point: `Top band has only ${bpTop.n} people / ${bpTop.cases} cases, so its rate is unreliable`, marks: 1 }], model: `The data support an association: the rate of new CHD rises with every band, from ${f1(BP[0].rate)} to ${f1(bpTop.rate)} per 1000, a dose–response that is consistent with a causal link. But this is a cohort study, not a trial, so confounding variables such as age, obesity or smoking may be linked to both blood pressure and CHD; it does not prove cause. The second part is wrong: in the top band ${bpTop.cases} of ${bpTop.n} people developed CHD, so ${bpTop.n - bpTop.cases} (${f0(bpTop.free)} %) did not; a risk factor raises the probability, it does not make disease certain. The top band also contains only ${bpTop.n} people and ${bpTop.cases} cases, so its rate is much less reliable than the rates for the large bands.`, commonErrors: "Only describing the trend; accepting 'will get it'." },
      { id: `q-${R}-d4`, ref: R, stmts: S(2), type: "short", marks: 4, stem: `${HYP} A newspaper headline says: "Eating oily fish twice a week cuts heart disease risk by 30 %." It is based on a survey in which 20,000 adults recorded their usual diet and were followed for 8 years. Evaluate the headline. (4 marks)`, scheme: [{ point: "Observational / survey study: shows an association, not that fish causes the lower risk", marks: 1 }, { point: "Confounding variables: people who eat oily fish may exercise more, smoke less, have higher incomes or healthier diets overall", marks: 1 }, { point: "30 % is a relative reduction; the absolute reduction (baseline risk) is not given", marks: 1 }, { point: "Diet was self-reported (once) and may be inaccurate or change over 8 years; large sample is a strength but a trial is needed to show cause", marks: 1 }], model: "The headline claims cause ('cuts'), but the evidence is from an observational cohort, which can show only that eating oily fish is associated with a lower risk. People who eat oily fish twice a week may also exercise more, smoke less, eat less saturated fat or have higher incomes, and these confounding variables could explain some or all of the difference. The 30 % is a relative reduction; without the baseline risk we do not know how many fewer people per 1000 were affected, which may be small. Diet was self-reported and may be inaccurate or change over 8 years. The large sample of 20,000 is a strength, but a randomised trial would be needed to show cause.", commonErrors: "Accepting the claim because the sample is large." },
      // ---- extended ----
      { id: `q-${R}-e1`, ref: R, stmts: S(1, 2), type: "extended", marks: 6, stem: "Extended response. Using evidence from cohort studies and from randomised controlled trials, evaluate the claim that a high blood cholesterol concentration is a cause of coronary heart disease. Include how cholesterol could contribute to CHD. (6 marks)", scheme: [{ point: "Mechanism: high (LDL) cholesterol → more lipid enters and stays in artery walls → atheroma in coronary arteries → thrombosis / myocardial infarction", marks: 1 }, { point: "Cohort evidence: higher cholesterol associated with higher CHD rates (e.g. lower cholesterol associated with lower IHD death at all ages)", marks: 1 }, { point: "Dose–response / consistent across many studies and ages supports cause", marks: 1 }, { point: "Limitation of cohorts: association only; confounding variables (diet, smoking, weight, genes)", marks: 1 }, { point: "Trial evidence: random allocation to cholesterol lowering v placebo reduced coronary deaths (e.g. 8.5 % to 5.0 %), so cause is supported", marks: 1 }, { point: "Limitations / conclusion: trial in people already with CHD; other risk factors also matter; cholesterol raises risk rather than guaranteeing CHD", marks: 1 }], levels: "Level 3 (5–6): a mechanism linked to atheroma; cohort and trial evidence described and their strengths and limitations compared; a reasoned conclusion that uses the language of risk. Level 2 (3–4): evidence of both kinds mentioned with some evaluation; mechanism or conclusion incomplete. Level 1 (1–2): statements that cholesterol is linked to CHD with little evaluation.", model: "High blood cholesterol, especially cholesterol carried in LDL, is associated with more lipid entering and staying in artery walls, so atheroma is more likely to form in the coronary arteries; a thrombus on an atheroma can then cause a myocardial infarction, so there is a plausible mechanism. Cohort studies support a link: in 61 cohorts of almost 900,000 adults, a 1 mmol/L lower cholesterol was associated with a lower death rate from ischaemic heart disease at every age, with a dose–response and a consistent pattern. However, cohort studies show only an association, because people with high cholesterol may differ in diet, smoking, weight or genes. Randomised trials deal with this: in the 4S trial, people allocated at random to a cholesterol-lowering drug had fewer coronary deaths than the placebo group (about 5.0 % against 8.5 %), and because randomisation balances other risk factors, the difference can be put down to lowering cholesterol. Limitations remain: the trial studied people who already had CHD, the drug might have other effects, and CHD has several other risk factors. Overall the evidence strongly supports high blood cholesterol as a cause that increases the risk of CHD, not one that guarantees it.", commonErrors: "Only describing data; claiming cholesterol always leads to CHD." },
    ],
  };
})();
